"""Manually authored subject spans: immutable supplied paragraph indices, exact equipment."""
SPANS=[]
def add(a,b,kind,key,title='',country='PL',**kw):SPANS.append(dict(a=a,b=b,kind=kind,asset_id=key,title=title,country=country,**kw))
def v(a,b,key,title,country='PL',cap=10):add(a,b,'archive',key,title,country,archive_cap=cap)
def p(a,b,key,title,country='PL',**kw):add(a,b,'photo',key,title,country,**kw)
def t(a,b,key,title,country='PL'):add(a,b,'turntable','model-'+key,title,country)
def g(a,b,title,*nodes):add(a,b,'graphic','original',title,nodes=list(nodes))
def c(a,b,title,left,right):add(a,b,'compare','original',title,sides=[left,right])
